    public void processOperation(METUpdateExciseRegisterContract _contract)
    {
        /*
- We  need to add a filter - Sales Order for now on the batch job - Done.
- if sales oder other then invoiced selected - validate and throw error saying need to select invoiced sales order - done
- go to this sales order, invoice details - done

- Once we have all details
          - first check if we have a Rgeistrty lines
                - same site
               - +ve qty (Purcahse order, sales return
                - same item ------ done till here
                - open lines
                    - received qty received from powerapp is in the purchase unit - case - 6 case
                            - qty is always in inventory unit of measure eg ea(convert that based on the setup) - 6 * (2 - from setup) = 12


            - if we have above line
                        - insert sales order lines
                            lodgementId should be picked from above purchase order line
                            OriginPartyId of the customer
                            qty,receipt qty is also negative
                        - closed, available qty always 0
                        - receipt qty in sales unit
                            - qty in eac
        */
        // logic to get invoice details of the sales order
        //Once we have all details
        //- first check if we have a Rgeistrty lines
         //       - same site amd item id
        SalesId salesId;
        salesId =   _contract.parmSalesId();
        int    i;
        i    = 0;
        ttsbegin;

        while select salesId from salesTable where salesTable.SalesId == salesId
            join custInvoiceJour
                where SalesTable.salesid == custInvoiceJour.salesid
            join custInvoiceTrans
                where custInvoiceJour.SalesId == custInvoiceTrans.SalesId
            join metExciseRegisterEntry
                where custInvoiceTrans.ItemId == metExciseRegisterEntry.ItemNo
            &&  metExciseRegisterEntry.Site == salesTable.InventSiteId
       
        
        {
            metExciseRegisterEntry.Lodgement              = int2Str(i);
            metExciseRegisterEntry.OriginType             = METOriginType::SalesOrder;
            metExciseRegisterEntry.OriginNumber           = salesTable.SalesId;
            metExciseRegisterEntry.OriginDocumentNumber   = custInvoiceJour.InvoiceId;
            metExciseRegisterEntry.AvailableQuantity      = 0;
            metExciseRegisterEntry.Closed                 = NoYes::Yes;
            metExciseRegisterEntry.insert();
            i = i+1;
        }
        ttscommit;
    }

