    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// This method calcultes the available qty 
    /// </summary>
    /// <param name = "_metExciseRegisterEntrySales"> METExciseRegister table</param>
 
    public void availableQtyCalculation(metExciseRegisterEntry _metExciseRegisterEntrySales)
    {
        METExciseRegisterEntry metExciseRegisterEntryPurch;
        ttsbegin;

        while select forupdate metExciseRegisterEntryPurch
            where _metExciseRegisterEntrySales.ItemNo    == metExciseRegisterEntryPurch.ItemNo
            &&    _metExciseRegisterEntrySales.LotId     == metExciseRegisterEntryPurch.LotId
            &&    metExciseRegisterEntryPurch.OriginType == METOriginType::PurchaseOrder
            &&    metExciseRegisterEntryPurch.AvailableQuantity   > 0
        {
           
            metExciseRegisterEntryPurch.AvailableQuantity = metExciseRegisterEntryPurch.AvailableQuantity + _metExciseRegisterEntrySales.Quantity;
            if(metExciseRegisterEntryPurch.AvailableQuantity == 0)
            {
                metExciseRegisterEntryPurch.Closed = NoYes::Yes;
                
            }
            metExciseRegisterEntryPurch.update();
        }
       
        ttscommit;

       
    }
